       .error.is-visible {
         display: block;
       }

       button {
         width: 100%;
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.4rem;
         color: #140f2d;
         background: linear-gradient(135deg, var(--accent-strong), #c4b5fd);
         box-shadow: 0 1rem 2rem rgba(139, 92, 246, 0.25);
         font: inherit;
         font-weight: 800;
         cursor: pointer;
       }

       button:hover {
         filter: brightness(1.06);
       }

       button:focus-visible {
         outline: 3px solid var(--ring);
         outline-offset: 4px;
