           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
         }
       }

       @media (forced-colors: active) {
         .card,
         .radio-option,
         button {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         .required-marker,
         .error,
         .status {
           color: CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <main id="main">
       <section class="card" aria-labelledby="page-title">
         <h1 id="page-title">Notification preferences</h1>
         <p class="intro">Tell us where updates should reach you first.</p>

         <form id="notification-form" novalidate>
           <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

           <div class="form-field">
             <fieldset aria-describedby="notification-hint notification-error">
               <legend>
                 How do you prefer to receive notifications?
                 <span class="required-marker" aria-hidden="true">*</span>
               </legend>
               <p id="notification-hint" class="hint">Choose one notification method.</p>

               <div class="options">
                 <label class="radio-option" for="notification-email">
                   <input id="notification-email" type="radio" name="notification-preference" value="email" required>
                   <span>Email</span>
                 </label>

                 <label class="radio-option" for="notification-sms">
                   <input id="notification-sms" type="radio" name="notification-preference" value="sms" required>
                   <span>SMS</span>
                 </label>

                 <label class="radio-option" for="notification-push">
                   <input id="notification-push" type="radio" name="notification-preference" value="push" required>
                   <span>Push Notifications</span>
                 </label>
               </div>

               <p id="notification-error" class="error">Error: Choose how you prefer to receive notifications.</p>
             </fieldset>
           </div>

           <button type="submit">Save preference</button>
           <p id="form-status" class="status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#notification-form");
       const radios = [...document.querySelectorAll('input[name="notification-preference"]')];
       const error = document.querySelector("#notification-error");
       const status = document.querySelector("#form-status");

       function setErrorState(hasError) {
         error.classList.toggle("is-visible", hasError);
         radios.forEach((radio) => {
           radio.setAttribute("aria-invalid", String(hasError));
         });
       }

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const selected = radios.find((radio) => radio.checked);

         if (!selected) {
           setErrorState(true);
           status.textContent = "";
           radios[0].focus();
           return;
         }

         setErrorState(false);
         status.textContent = `Preference saved: ${selected.closest("label").innerText}.`;
       });

       radios.forEach((radio) => {
         radio.addEventListener("change", () => {
           setErrorState(false);
           status.textContent = "";
         });
       });
     </script>
   </body>
 </html>

