      <section class="card" aria-labelledby="page-title">
        <h1 id="page-title">Notification preferences</h1>
        <p class="intro">Tell us where updates should reach you first.</p>

        <form id="notification-form" novalidate>
          <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

          <div class="form-field">
            <fieldset id="notification-fieldset" aria-describedby="notification-hint">
              <legend>
                How do you prefer to receive notifications?
                <span class="required-marker" aria-hidden="true">*</span>
              </legend>
              <p id="notification-hint" class="hint">Choose one notification method.</p>

