  await page.setContent(fs.readFileSync(pagePath, 'utf8'), { waitUntil: 'load' });
  await page.addScriptTag({ path: require.resolve('axe-core/axe.min.js') });

  const initial = await scan(page, 'initial');
  await page.locator('button[type="submit"]').click();
  const invalidSubmit = await scan(page, 'invalid-submit');
  await browser.close();

  const results = [initial, invalidSubmit];
  console.log(JSON.stringify(results, null, 2));
  process.exit(results.some((result) => result.wcag.length) ? 1 : 0);
})().catch((error) => {
  console.error(error);
  process.exit(1);
});
