 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Notification Preferences</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1020;
         --panel: #141b2f;
         --panel-strong: #1c2540;
         --text: #f8fafc;
         --muted: #b9c3d6;
         --accent: #8b5cf6;
         --accent-strong: #a78bfa;
         --error: #fca5a5;
         --success: #86efac;
         --ring: #facc15;
         --border: #33415f;
       }

       * {
         box-sizing: border-box;
       }

       body {
         min-height: 100vh;
         margin: 0;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         line-height: 1.5;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(139, 92, 246, 0.28), transparent 32rem),
           radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.18), transparent 30rem),
           var(--bg);
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         z-index: 10;
         transform: translateY(-160%);
         border-radius: 999px;
         padding: 0.65rem 1rem;
         color: #111827;
         background: var(--ring);
         font-weight: 700;
         text-decoration: none;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid #ffffff;
         outline-offset: 3px;
       }

       main {
         display: grid;
         min-height: 100vh;
         place-items: center;
         padding: 2rem 1rem;
       }

       .card {
         width: min(100%, 38rem);
         border: 1px solid rgba(255, 255, 255, 0.12);
         border-radius: 1.5rem;
         padding: clamp(1.5rem, 5vw, 3rem);
         background: linear-gradient(145deg, rgba(20, 27, 47, 0.96), rgba(11, 16, 32, 0.92));
         box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.38);
       }

       h1 {
         margin: 0 0 0.65rem;
         font-size: clamp(2rem, 6vw, 3.5rem);
         line-height: 1;
         letter-spacing: -0.05em;
       }

       .intro,
       .required-note,
       .hint {
         color: var(--muted);
       }

       .intro {
         margin: 0 0 2rem;
         font-size: 1.05rem;
       }

       .required-note {
         margin: 0 0 1rem;
         font-size: 0.95rem;
       }

       .form-field {
         margin: 0 0 1.5rem;
       }

       fieldset {
         margin: 0;
         border: 0;
         padding: 0;
       }

       legend {
         margin: 0 0 0.35rem;
         padding: 0;
         color: var(--text);
         font-size: 1.2rem;
         font-weight: 800;
       }

       .required-marker {
         color: var(--accent-strong);
       }

       .hint {
         margin: 0 0 1rem;
       }

       .options {
         display: grid;
         gap: 0.8rem;
       }

       .radio-option {
         display: flex;
         align-items: center;
         gap: 0.85rem;
         min-height: 3.75rem;
         border: 1px solid var(--border);
         border-radius: 1rem;
         padding: 1rem;
         background: rgba(28, 37, 64, 0.72);
         cursor: pointer;
         transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
       }

       .radio-option:hover {
         border-color: var(--accent-strong);
         background: rgba(42, 52, 86, 0.9);
         transform: translateY(-1px);
       }

       input[type="radio"] {
         width: 1.25rem;
         height: 1.25rem;
         margin: 0;
         accent-color: var(--accent);
         flex: 0 0 auto;
       }

       input[type="radio"]:focus-visible {
         outline: 3px solid var(--ring);
         outline-offset: 4px;
       }

       .radio-option:has(input[type="radio"]:checked) {
         border-color: var(--accent-strong);
         background: linear-gradient(135deg, rgba(139, 92, 246, 0.28), rgba(28, 37, 64, 0.9));
       }

       .error {
         display: none;
         margin: 0.9rem 0 0;
         color: var(--error);
         font-weight: 700;
       }

       .error.is-visible {
         display: block;
       }

       button {
         width: 100%;
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.4rem;
         color: #140f2d;
         background: linear-gradient(135deg, var(--accent-strong), #c4b5fd);
         box-shadow: 0 1rem 2rem rgba(139, 92, 246, 0.25);
         font: inherit;
         font-weight: 800;
         cursor: pointer;
       }

       button:hover {
         filter: brightness(1.06);
       }

       button:focus-visible {
         outline: 3px solid var(--ring);
         outline-offset: 4px;
       }

       .status {
         min-height: 1.5rem;
         margin: 1rem 0 0;
         color: var(--success);
         font-weight: 700;
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
         }
       }

       @media (forced-colors: active) {
         .card,
         .radio-option,
         button {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         .required-marker,
         .error,
         .status {
           color: CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <main id="main">
       <section class="card" aria-labelledby="page-title">
         <h1 id="page-title">Notification preferences</h1>
         <p class="intro">Tell us where updates should reach you first.</p>

         <form id="notification-form" novalidate>
           <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

           <div class="form-field">
             <fieldset id="notification-fieldset" aria-describedby="notification-hint">
               <legend>
                 How do you prefer to receive notifications?
                 <span class="required-marker" aria-hidden="true">*</span>
               </legend>
               <p id="notification-hint" class="hint">Choose one notification method.</p>

               <div class="options">
                 <label class="radio-option" for="notification-email">
                   <input id="notification-email" type="radio" name="notification-preference" value="email" required>
                   <span>Email</span>
                 </label>

                 <label class="radio-option" for="notification-sms">
                   <input id="notification-sms" type="radio" name="notification-preference" value="sms" required>
                   <span>SMS</span>
                 </label>

                 <label class="radio-option" for="notification-push">
                   <input id="notification-push" type="radio" name="notification-preference" value="push" required>
                   <span>Push Notifications</span>
                 </label>
               </div>

               <p id="notification-error" class="error">Error: Choose how you prefer to receive notifications.</p>
             </fieldset>
           </div>

           <button type="submit">Save preference</button>
           <p id="form-status" class="status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#notification-form");
       const fieldset = document.querySelector("#notification-fieldset");
       const radios = [...document.querySelectorAll('input[name="notification-preference"]')];
       const error = document.querySelector("#notification-error");
       const status = document.querySelector("#form-status");

       function setErrorState(hasError) {
         error.classList.toggle("is-visible", hasError);
         fieldset.setAttribute(
           "aria-describedby",
           hasError ? "notification-hint notification-error" : "notification-hint"
         );
         radios.forEach((radio) => {
           if (hasError) {
             radio.setAttribute("aria-invalid", "true");
           } else {
             radio.removeAttribute("aria-invalid");
           }
         });
       }

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const selected = radios.find((radio) => radio.checked);

         if (!selected) {
           setErrorState(true);
           status.textContent = "";
           radios[0].focus();
           return;
         }

         setErrorState(false);
         status.textContent = `Preference saved: ${selected.closest("label").innerText}.`;
       });

       radios.forEach((radio) => {
         radio.addEventListener("change", () => {
           setErrorState(false);
           status.textContent = "";
         });
       });
     </script>
   </body>
 </html>

